WITH MathSubjectUnitsCV AS ( SELECT ata.ACADEMIC_YEAR_DESC, (STDDEV_SAMP(ccso.TOTAL_UNITS) / NULLIF(AVG(ccso.TOTAL_UNITS), 0)) AS coefficient_of_variation FROM COURSE_CATALOG_SUBJECT_OFFERED ccso JOIN ACADEMIC_TERMS_ALL ata ON ccso.TERM_CODE = ata.TERM_CODE WHERE ccso.DEPARTMENT_NAME = 'Mathematics' GROUP BY ata.ACADEMIC_YEAR_DESC ORDER BY ata.ACADEMIC_YEAR_DESC ), MathLibraryUnitsCV AS ( SELECT ata.ACADEMIC_YEAR, ata.ACADEMIC_YEAR_DESC, CASE WHEN AVG(ccso.TOTAL_UNITS) = 0 OR AVG(ccso.TOTAL_UNITS) IS NULL THEN NULL ELSE STDDEV(ccso.TOTAL_UNITS) / AVG(ccso.TOTAL_UNITS) END AS coefficient_of_variation_total_units FROM LIBRARY_RESERVE_MATRL_DETAIL lrm JOIN ACADEMIC_TERMS_ALL ata ON lrm.TERM_CODE = ata.TERM_CODE JOIN COURSE_CATALOG_SUBJECT_OFFERED ccso ON ata.TERM_CODE = ccso.TERM_CODE AND lrm.SUBJECT_ID = ccso.SUBJECT_ID WHERE lrm.LIBRARY_MATERIAL_STATUS_KEY = 'U' AND ccso.DEPARTMENT_NAME = 'Mathematics' GROUP BY ata.ACADEMIC_YEAR, ata.ACADEMIC_YEAR_DESC ORDER BY ata.ACADEMIC_YEAR ) SELECT msyc.ACADEMIC_YEAR_DESC, msyc.coefficient_of_variation AS subject_units_cv, mlcv.coefficient_of_variation_total_units AS library_units_cv FROM MathSubjectUnitsCV msyc JOIN MathLibraryUnitsCV mlcv ON msyc.ACADEMIC_YEAR_DESC = mlcv.ACADEMIC_YEAR_DESC ORDER BY msyc.ACADEMIC_YEAR_DESC;